#!/usr/bin/env python3
"""MCP server generated by gpt-lifeboat from a Custom GPT action schema.

One MCP tool per API operation; the operations live in operations.json next to this file.
Credentials are read from environment variables (or a .env file in this folder) and are
never written anywhere. Needs the official MCP Python SDK, version 2:  pip install "mcp>=2,<3"

    python server.py                   stdio transport (Claude Desktop, Claude Code, local clients)
    python server.py --http            Streamable HTTP on 127.0.0.1:8000/mcp
    python server.py --http --host 0.0.0.0 --port 8080
    python server.py --check           print the tools and which variables are set, then exit

The HTTP mode has no authentication of its own. Anyone who can reach it can call your
API with your key. Keep it on localhost or put it behind something that authenticates.
"""

from __future__ import annotations

import argparse
import base64
import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request
from pathlib import Path

HERE = Path(__file__).resolve().parent
MAX_RESPONSE_CHARS = 100_000
TIMEOUT_SECONDS = 30


def load_dotenv(path=HERE / ".env"):
    """Read KEY=VALUE lines from .env without overriding variables that are already set."""
    if not path.is_file():
        return
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, _, value = line.partition("=")
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
            value = value[1:-1]
        os.environ.setdefault(key.strip(), value)


def load_config(path=HERE / "operations.json"):
    return json.loads(path.read_text(encoding="utf-8"))


class ToolInputError(ValueError):
    """The arguments or the configuration do not allow the request to be built."""


def _text(value):
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (dict, list)):
        return json.dumps(value)
    return str(value)


def base_url(action, env):
    return (env.get(action["env"]["base_url"]) or action.get("base_url") or "").rstrip("/")


def auth_parts(action, env):
    """Return (headers, query) carrying the credential for this action, taken from the environment."""
    auth = action.get("auth") or {"type": "none"}
    names = action["env"]
    if auth["type"] == "none":
        return {}, {}
    var = names["access_token"] if auth["type"] == "oauth" else names["api_key"]
    secret = env.get(var, "")
    if not secret:
        raise ToolInputError("Environment variable %s is not set; it holds the credential for %s." % (var, base_url(action, env) or "this API"))
    if auth["type"] == "oauth":
        return {"Authorization": "Bearer " + secret}, {}
    kind = auth.get("auth_type", "bearer")
    if kind == "bearer":
        return {"Authorization": "Bearer " + secret}, {}
    if kind == "basic":
        if ":" in secret:  # user:password given in clear; encode it
            secret = base64.b64encode(secret.encode()).decode()
        return {"Authorization": "Basic " + secret}, {}
    if kind == "query":
        return {}, {auth.get("query_param", "api_key"): secret}
    return {auth.get("custom_header_name") or "X-Api-Key": secret}, {}


def build_request(config, tool, arguments, env=os.environ):
    """Translate a tool call into (method, url, headers, body bytes or None)."""
    op = next((o for o in config["operations"] if o["tool"] == tool), None)
    if op is None:
        raise ToolInputError("Unknown tool: %s" % tool)
    action = config["actions"][op["action"]]
    root = base_url(action, env)
    if not root:
        raise ToolInputError("No base URL. Set %s to the API's address, for example https://api.example.com" % action["env"]["base_url"])
    arguments = arguments or {}
    missing = [name for name in op["input_schema"].get("required", []) if name not in arguments]
    if missing:
        raise ToolInputError("Missing required argument(s): %s" % ", ".join(missing))

    path, query, headers = op["path"], [], {"Accept": "application/json", "User-Agent": "gpt-lifeboat-mcp/1"}
    for arg, where in op["arg_map"].items():
        if arg not in arguments or arguments[arg] is None:
            continue
        value = arguments[arg]
        if where["in"] == "path":
            path = path.replace("{%s}" % where["name"], urllib.parse.quote(_text(value), safe=""))
        elif where["in"] == "query":
            for item in value if isinstance(value, list) else [value]:
                query.append((where["name"], _text(item)))
        elif where["in"] == "header":
            headers[where["name"]] = _text(value)
    if "{" in path:
        raise ToolInputError("Path %s still has an unfilled parameter." % path)

    auth_headers, auth_query = auth_parts(action, env)
    headers.update(auth_headers)
    query.extend(auth_query.items())

    data = None
    if op.get("body_type") and arguments.get("body") is not None:
        body = arguments["body"]
        if op["body_type"] == "application/x-www-form-urlencoded":
            if not isinstance(body, dict):
                raise ToolInputError("body must be an object for a form-encoded request")
            data = urllib.parse.urlencode({k: _text(v) for k, v in body.items()}).encode()
        elif op["body_type"] == "text/plain":
            data = _text(body).encode()
        else:
            data = json.dumps(body).encode()
        headers["Content-Type"] = op["body_type"]

    url = root + path + ("?" + urllib.parse.urlencode(query) if query else "")
    return op["method"], url, headers, data


class _SameHostRedirects(urllib.request.HTTPRedirectHandler):
    """Follow redirects only within the same host, so the credential never goes elsewhere."""

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        if urllib.parse.urlsplit(newurl).netloc != urllib.parse.urlsplit(req.full_url).netloc:
            raise urllib.error.HTTPError(req.full_url, code, "Redirect to another host refused: %s" % newurl, headers, fp)
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def send(method, url, headers, data):
    """Perform the HTTP request. Returns (ok, text)."""
    request = urllib.request.Request(url, data=data, headers=headers, method=method)
    opener = urllib.request.build_opener(_SameHostRedirects)
    try:
        with opener.open(request, timeout=TIMEOUT_SECONDS) as response:
            status, raw = response.status, response.read(MAX_RESPONSE_CHARS * 4 + 1)
    except urllib.error.HTTPError as exc:
        body = exc.read(MAX_RESPONSE_CHARS).decode("utf-8", "replace") if exc.fp else ""
        return False, "HTTP %s %s\n%s" % (exc.code, exc.reason, body)
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        return False, "Request failed: %s" % exc
    text = raw.decode("utf-8", "replace")
    if len(text) > MAX_RESPONSE_CHARS:
        text = text[:MAX_RESPONSE_CHARS] + "\n[response cut at %d characters]" % MAX_RESPONSE_CHARS
    return True, text if text else "HTTP %s (empty body)" % status


def make_server(config):
    from mcp import types
    from mcp.server.lowlevel import Server

    async def list_tools(ctx, params):
        tools = []
        for op in config["operations"]:
            tools.append(
                types.Tool(
                    name=op["tool"],
                    description=op["description"],
                    input_schema=op["input_schema"],
                    annotations=types.ToolAnnotations(read_only_hint=bool(op.get("read_only")), open_world_hint=True),
                )
            )
        return types.ListToolsResult(tools=tools)

    async def call_tool(ctx, params):
        import anyio

        try:
            request = build_request(config, params.name, params.arguments or {})
        except ToolInputError as exc:
            return types.CallToolResult(content=[types.TextContent(type="text", text=str(exc))], is_error=True)
        ok, text = await anyio.to_thread.run_sync(lambda: send(*request))
        return types.CallToolResult(content=[types.TextContent(type="text", text=text)], is_error=not ok)

    return Server(config.get("server_name") or "gpt-lifeboat", version="1.0.0", on_list_tools=list_tools, on_call_tool=call_tool)


def check(config):
    print("%d tool(s):" % len(config["operations"]))
    for op in config["operations"]:
        print("  %-40s %s %s" % (op["tool"], op["method"], op["path"]))
    for action in config["actions"]:
        auth = action.get("auth") or {"type": "none"}
        print("API %s (auth: %s)" % (base_url(action, os.environ) or "NO BASE URL", auth["type"]))
        wanted = [] if auth["type"] == "none" else [action["env"]["access_token" if auth["type"] == "oauth" else "api_key"]]
        if not base_url(action, os.environ):
            wanted.append(action["env"]["base_url"])
        for var in wanted:
            print("  %s: %s" % (var, "set" if os.environ.get(var) else "NOT SET"))


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    parser.add_argument("--http", action="store_true", help="serve Streamable HTTP instead of stdio")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, default=8000)
    parser.add_argument("--check", action="store_true", help="print tools and configuration, then exit")
    args = parser.parse_args(argv)

    load_dotenv()
    config = load_config()
    if args.check:
        check(config)
        return 0
    try:
        server = make_server(config)
    except ImportError:
        print('The MCP Python SDK (version 2) is not installed. Run: pip install "mcp>=2,<3"', file=sys.stderr)
        return 1

    if args.http:
        import uvicorn

        app = server.streamable_http_app(host=args.host, stateless_http=True, json_response=True)
        uvicorn.run(app, host=args.host, port=args.port, log_level="warning")
        return 0

    import anyio
    from mcp.server.stdio import stdio_server

    async def run_stdio():
        async with stdio_server() as (read_stream, write_stream):
            await server.run(read_stream, write_stream, server.create_initialization_options())

    anyio.run(run_stdio)
    return 0


if __name__ == "__main__":
    sys.exit(main())
